import os
import secrets
import base64
import hashlib
import urllib.parse
from typing import Dict, Optional, Tuple

import requests


class Auth0PKCELoginFlow:
    """Implements a PKCE-based federated login flow using the Auth0 Authentication API."""

    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        redirect_uri: Optional[str] = None,
    ) -> None:
        self.domain = domain or os.environ.get("AUTH0_DOMAIN")
        self.client_id = client_id or os.environ.get("AUTH0_CLIENT_ID")
        self.redirect_uri = redirect_uri or os.environ.get(
            "AUTH0_REDIRECT_URI", "http://localhost:3000/callback"
        )
        if not self.domain or not self.client_id:
            raise ValueError(
                "AUTH0_DOMAIN and AUTH0_CLIENT_ID must be provided via constructor or environment variables."
            )

    @staticmethod
    def _generate_code_verifier() -> str:
        return secrets.token_urlsafe(64)

    @staticmethod
    def _generate_code_challenge(code_verifier: str) -> str:
        digest = hashlib.sha256(code_verifier.encode("utf-8")).digest()
        return base64.urlsafe_b64encode(digest).rstrip(b"=").decode("utf-8")

    def get_authorization_url(
        self, connection: Optional[str] = None, state: Optional[str] = None
    ) -> Tuple[str, str, str]:
        """Generates the Auth0 /authorize URL and returns it alongside the generated code_verifier and state."""
        code_verifier = self._generate_code_verifier()
        code_challenge = self._generate_code_challenge(code_verifier)
        state = state or secrets.token_urlsafe(16)

        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": "openid profile email",
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
            "state": state,
        }
        if connection:
            params["connection"] = connection

        query_string = urllib.parse.urlencode(params)
        authorize_url = f"https://{self.domain}/authorize?{query_string}"
        return authorize_url, code_verifier, state

    def exchange_code_for_token(
        self, authorization_code: str, code_verifier: str
    ) -> Dict:
        """Exchanges the authorization code and code_verifier for tokens at /oauth/token."""
        token_url = f"https://{self.domain}/oauth/token"
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": authorization_code,
            "redirect_uri": self.redirect_uri,
            "code_verifier": code_verifier,
        }
        headers = {"Content-Type": "application/x-www-form-urlencoded"}
        response = requests.post(token_url, data=payload, headers=headers)
        response.raise_for_status()
        return response.json()

    def get_user_info(self, access_token: str) -> Dict:
        """Retrieves user profile information from the /userinfo endpoint."""
        userinfo_url = f"https://{self.domain}/userinfo"
        headers = {"Authorization": f"Bearer {access_token}"}
        response = requests.get(userinfo_url, headers=headers)
        response.raise_for_status()
        return response.json()
